from pathlib import Path

path = Path('deduper/family_recertification_queue.py')
text = path.read_text()

old_doc = '''    """Crash-safe priority queue for BYE BITCH family recertification.\n\n    The SQLite table names retain their historical ``family_repair_*`` spelling\n    solely for in-place database compatibility. They are private storage names,\n    not current product terminology.\n    """'''
new_doc = '''    """Crash-safe priority queue for BYE BITCH family recertification.\n\n    Startup performs an idempotent in-place migration from historical\n    ``family_repair_*`` tables to the current ``family_recertification_*``\n    schema before any queue operations run.\n    """'''
if old_doc not in text:
    raise SystemExit('class docstring anchor missing')
text = text.replace(old_doc, new_doc, 1)

start = text.index('    def __init__(self, database) -> None:\n')
end = text.index('    def _priority_keys', start)
new_init = '''    def __init__(self, database) -> None:\n        self.database = database\n        with self.database._lock, self.database.connection:\n            self._migrate_legacy_schema()\n            self.database.connection.executescript(\n                """\n                CREATE TABLE IF NOT EXISTS family_recertification_jobs (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    deleted_key TEXT NOT NULL,\n                    protected_key TEXT NOT NULL,\n                    status TEXT NOT NULL DEFAULT 'pending',\n                    attempt_count INTEGER NOT NULL DEFAULT 0,\n                    last_error TEXT,\n                    last_attempt_at TEXT,\n                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                    completed_at TEXT\n                );\n\n                CREATE TABLE IF NOT EXISTS family_recertification_members (\n                    recertification_id INTEGER NOT NULL REFERENCES family_recertification_jobs(id) ON DELETE CASCADE,\n                    priority INTEGER NOT NULL,\n                    asset_key TEXT NOT NULL,\n                    PRIMARY KEY (recertification_id, asset_key),\n                    UNIQUE (recertification_id, priority)\n                );\n\n                CREATE INDEX IF NOT EXISTS family_recertification_status_idx\n                    ON family_recertification_jobs(status, id);\n                """\n            )\n            columns = {\n                str(row["name"])\n                for row in self.database.connection.execute(\n                    "PRAGMA table_info(family_recertification_jobs)"\n                ).fetchall()\n            }\n            if "attempt_count" not in columns:\n                self.database.connection.execute(\n                    "ALTER TABLE family_recertification_jobs ADD COLUMN attempt_count INTEGER NOT NULL DEFAULT 0"\n                )\n            if "last_error" not in columns:\n                self.database.connection.execute(\n                    "ALTER TABLE family_recertification_jobs ADD COLUMN last_error TEXT"\n                )\n            if "last_attempt_at" not in columns:\n                self.database.connection.execute(\n                    "ALTER TABLE family_recertification_jobs ADD COLUMN last_attempt_at TEXT"\n                )\n\n            self.database.connection.execute(\n                """\n                UPDATE family_recertification_jobs\n                SET status = 'retry',\n                    last_error = COALESCE(last_error, 'Application closed during family recertification')\n                WHERE status = 'running'\n                """\n            )\n            self.database.connection.execute(\n                """\n                UPDATE family_recertification_jobs\n                SET status = 'complete', completed_at = CURRENT_TIMESTAMP\n                WHERE status IN ('pending', 'running', 'retry')\n                  AND id NOT IN (\n                      SELECT MIN(id)\n                      FROM family_recertification_jobs\n                      WHERE status IN ('pending', 'running', 'retry')\n                      GROUP BY deleted_key\n                  )\n                """\n            )\n            self.database.connection.execute(\n                """\n                CREATE UNIQUE INDEX IF NOT EXISTS family_recertification_one_open_deleted_idx\n                ON family_recertification_jobs(deleted_key)\n                WHERE status IN ('pending', 'running', 'retry')\n                """\n            )\n\n    def _table_exists(self, name: str) -> bool:\n        row = self.database.connection.execute(\n            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",\n            (name,),\n        ).fetchone()\n        return row is not None\n\n    def _migrate_legacy_schema(self) -> None:\n        jobs_old = self._table_exists("family_repair_jobs")\n        members_old = self._table_exists("family_repair_members")\n        if not jobs_old and not members_old:\n            return\n        if jobs_old != members_old:\n            raise RuntimeError("incomplete legacy family recertification schema")\n\n        self.database.connection.executescript(\n            """\n            CREATE TABLE IF NOT EXISTS family_recertification_jobs (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                deleted_key TEXT NOT NULL,\n                protected_key TEXT NOT NULL,\n                status TEXT NOT NULL DEFAULT 'pending',\n                attempt_count INTEGER NOT NULL DEFAULT 0,\n                last_error TEXT,\n                last_attempt_at TEXT,\n                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                completed_at TEXT\n            );\n            CREATE TABLE IF NOT EXISTS family_recertification_members (\n                recertification_id INTEGER NOT NULL REFERENCES family_recertification_jobs(id) ON DELETE CASCADE,\n                priority INTEGER NOT NULL,\n                asset_key TEXT NOT NULL,\n                PRIMARY KEY (recertification_id, asset_key),\n                UNIQUE (recertification_id, priority)\n            );\n            """\n        )\n\n        legacy_columns = {\n            str(row["name"])\n            for row in self.database.connection.execute(\n                "PRAGMA table_info(family_repair_jobs)"\n            ).fetchall()\n        }\n        attempt_expr = "attempt_count" if "attempt_count" in legacy_columns else "0"\n        error_expr = "last_error" if "last_error" in legacy_columns else "NULL"\n        attempted_expr = "last_attempt_at" if "last_attempt_at" in legacy_columns else "NULL"\n        self.database.connection.execute(\n            f"""\n            INSERT OR IGNORE INTO family_recertification_jobs (\n                id, deleted_key, protected_key, status, attempt_count, last_error,\n                last_attempt_at, created_at, completed_at\n            )\n            SELECT id, deleted_key, protected_key, status, {attempt_expr}, {error_expr},\n                   {attempted_expr}, created_at, completed_at\n            FROM family_repair_jobs\n            """\n        )\n        self.database.connection.execute(\n            """\n            INSERT OR IGNORE INTO family_recertification_members (\n                recertification_id, priority, asset_key\n            )\n            SELECT repair_id, priority, asset_key\n            FROM family_repair_members\n            """\n        )\n\n        legacy_jobs = int(self.database.connection.execute(\n            "SELECT COUNT(*) AS count FROM family_repair_jobs"\n        ).fetchone()["count"])\n        modern_jobs = int(self.database.connection.execute(\n            "SELECT COUNT(*) AS count FROM family_recertification_jobs"\n        ).fetchone()["count"])\n        legacy_members = int(self.database.connection.execute(\n            "SELECT COUNT(*) AS count FROM family_repair_members"\n        ).fetchone()["count"])\n        modern_members = int(self.database.connection.execute(\n            "SELECT COUNT(*) AS count FROM family_recertification_members"\n        ).fetchone()["count"])\n        if modern_jobs < legacy_jobs or modern_members < legacy_members:\n            raise RuntimeError("family recertification schema migration verification failed")\n\n        orphan = self.database.connection.execute(\n            """\n            SELECT 1\n            FROM family_recertification_members m\n            LEFT JOIN family_recertification_jobs j ON j.id = m.recertification_id\n            WHERE j.id IS NULL\n            LIMIT 1\n            """\n        ).fetchone()\n        if orphan is not None:\n            raise RuntimeError("family recertification schema migration produced orphan members")\n\n        self.database.connection.execute("DROP TABLE family_repair_members")\n        self.database.connection.execute("DROP TABLE family_repair_jobs")\n\n'''
text = text[:start] + new_init + text[end:]
text = text.replace('family_repair_members', 'family_recertification_members')
text = text.replace('family_repair_jobs', 'family_recertification_jobs')
text = text.replace('repair_id = ?', 'recertification_id = ?')
text = text.replace('INSERT INTO family_recertification_members (repair_id, priority, asset_key)', 'INSERT INTO family_recertification_members (recertification_id, priority, asset_key)')
path.write_text(text)

# Add migration-focused tests.
test = Path('tests/test_family_recertification_schema_migration.py')
test.write_text('''import tempfile\nimport unittest\nfrom pathlib import Path\n\nfrom deduper.certified_database import CertifiedDatabase\nfrom deduper.family_recertification_queue import FamilyRecertificationQueue\n\n\nclass FamilyRecertificationSchemaMigrationTests(unittest.TestCase):\n    def test_legacy_tables_are_copied_verified_and_dropped(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            db = CertifiedDatabase(Path(directory) / "deduper.sqlite3")\n            with db.connection:\n                db.connection.executescript("""\n                    CREATE TABLE family_repair_jobs (\n                        id INTEGER PRIMARY KEY AUTOINCREMENT, deleted_key TEXT NOT NULL,\n                        protected_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\n                        attempt_count INTEGER NOT NULL DEFAULT 0, last_error TEXT,\n                        last_attempt_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                        completed_at TEXT\n                    );\n                    CREATE TABLE family_repair_members (\n                        repair_id INTEGER NOT NULL REFERENCES family_repair_jobs(id) ON DELETE CASCADE,\n                        priority INTEGER NOT NULL, asset_key TEXT NOT NULL,\n                        PRIMARY KEY (repair_id, asset_key), UNIQUE (repair_id, priority)\n                    );\n                    INSERT INTO family_repair_jobs\n                        (id, deleted_key, protected_key, status, attempt_count, last_error)\n                    VALUES (7, 'gone.jpg', 'keep.jpg', 'retry', 3, 'saved failure');\n                    INSERT INTO family_repair_members (repair_id, priority, asset_key)\n                    VALUES (7, 0, 'keep.jpg'), (7, 1, 'other.jpg');\n                """)\n            queue = FamilyRecertificationQueue(db)\n            pending = queue.pending()\n            self.assertEqual(len(pending), 1)\n            self.assertEqual(pending[0].recertification_id, 7)\n            self.assertEqual(pending[0].priority_keys, ('keep.jpg', 'other.jpg'))\n            names = {row['name'] for row in db.connection.execute(\n                "SELECT name FROM sqlite_master WHERE type = 'table'"\n            )}\n            self.assertNotIn('family_repair_jobs', names)\n            self.assertNotIn('family_repair_members', names)\n            self.assertIn('family_recertification_jobs', names)\n            self.assertIn('family_recertification_members', names)\n            FamilyRecertificationQueue(db)\n            db.close()\n\n\nif __name__ == '__main__':\n    unittest.main()\n''')
